const parseCsv=t=>{const r=[];let c='',row=[],q=false;t=t.replace(/^﻿/,'');for(let i=0;i<t.length;i++){const x=t[i];if(q){if(x==='"'&&t[i+1]==='"'){c+='"';i++}else if(x==='"')q=false;else c+=x}else if(x==='"')q=true;else if(x===','){row.push(c);c=''}else if(x==='\n'){row.push(c);r.push(row);row=[];c=''}else if(x!=='\r')c+=x}if(c||row.length){row.push(c);r.push(row)}const h=r.shift()||[];return r.filter(x=>x.some(Boolean)).map(x=>Object.fromEntries(h.map((k,i)=>[k.trim().toLowerCase(),(x[i]||'').trim()])))};
