const blocked=o=>(o.blockers||[]).some(b=>!b.resolved);
function needFollow(){return S.enquiries.filter(x=>x.status==='New'||x.status==='In progress').map(x=>{const f=S.followups.filter(y=>y.enquiry===x.id||y.customer===x.customer);return{x,open:f.find(y=>y.status==='Open'),last:lastContact(x.customer)}}).filter(r=>!r.open||r.open.due<=today())}
function lastContact(c){const h=[...S.followups.filter(y=>y.customer===c&&y.status==='Done').map(y=>y.doneAt||y.created),...S.enquiries.filter(y=>y.customer===c).map(y=>y.created)].sort();return h[h.length-1]}
V.overview=()=>{const K=[],Q=[];if(S.offer!=='erp'){K.push(['Open enquiries',S.enquiries.filter(x=>['New','In progress'].includes(x.status)).length,'enquiries'],['Quotations awaiting decision',S.quotes.filter(x=>['Draft','Sent'].includes(x.status)).length,'quotes'],['Leads needing follow-up',needFollow().length,'followups']);Q.push(...needFollow().slice(0,6).map(r=>[`Follow up: ${nm('customers',r.x.customer)}`,'enquiries']))}if(S.offer!=='crm'){const o=S.orders.filter(x=>!['Shipped','Delivered'].includes(x.stage));K.push(['Orders in production',o.length,'orders'],['Delayed or blocked',o.filter(x=>late(x)||blocked(x)).length,'orders'],['Items below reorder',S.products.filter(p=>+p.stock<=+(p.reorder||0)&&+p.reorder>0).length,'stock']);Q.push(...o.filter(x=>late(x)||blocked(x)).slice(0,6).map(x=>[`${x.no} is ${blocked(x)?'blocked':'delayed'}`,'order/'+x.id]))}if(S.convs.some(c=>c.state==='Handoff'))Q.push(['Chat waiting for staff','chat']);shell('overview',`<div class="grid">${K.map(k=>`<div class="kpi" data-go="#/${k[2]}" style="cursor:pointer"><b>${k[1]}</b><span>${e(k[0])}</span></div>`).join('')}</div><div class="card"><h3>Needs attention</h3>${Q.length?Q.map(q=>`<p style="margin:6px 0"><button class="link" data-go="#/${q[1]}">${e(q[0])}</button></p>`).join(''):'<div class="empty">Nothing needs attention right now.</div>'}</div>${S.launch[1].done&&S.launch[2].done?'':`<div class="warn">Setup is not finished. <button class="link" data-go="#/launch">Open the launch plan</button></div>`}`)};
