A.imp=d=>{need(d.k);modal('Import CSV',`<p class="mut">Use a CSV with a <b>name</b> column. Other columns matching the fields are kept.</p><form data-f="imp" data-id="${d.k}"><input type="file" name="file" accept=".csv" required><div class="act"><button class="b p">Import</button></div></form>`)};
F.imp=async(d,k)=>{const rows=parseCsv(await d.file.text());if(!rows.length||!('name' in rows[0]))err('The file needs a "name" column.');let n=0,sk=0;for(const r of rows){if(!r.name){sk++;continue}if(S[k].some(x=>x.name.toLowerCase()===r.name.toLowerCase())){sk++;continue}const x={id:uid(),created:now(),...r};if(k==='products')Object.assign(x,{type:r.type||'Material',stock:0,bom:[]});S[k].push(x);n++}log('Imported '+k,`${n} added`);close();toast(`${n} added, ${sk} skipped`);route()};
V.enquiries=()=>shell('enquiries',`<div class="card">${table(['No.','Customer','Source','Product and quantity','Owner','Status',''],S.enquiries.slice().reverse().map(x=>[e(x.no),`<button class="link" data-go="#/customer/${x.customer}">${e(nm('customers',x.customer))}</button>`,e(x.source),e(`${x.product||''} ${x.qty?'× '+x.qty:''}`),e(by('users',x.owner)?.name||'Unassigned'),badge(x.status),can('enquiries','w')?button('Update','enq',{id:x.id})+(can('quotes','w')&&x.status!=='Lost'?' '+button('Quote','newQ',{enq:x.id}):''):'']),'No enquiries yet.')}</div>`,can('enquiries','w')?button('Add enquiry','enq',{},'b p'):'');
A.enq=d=>{need('enquiries');const x=d.id?by('enquiries',d.id):{};if(!S.customers.length)err('Add a customer first.');modal(d.id?'Update enquiry':'Add enquiry',form('enq',d.id,[fld('Customer','customer',{req:1,opts:S.customers.map(c=>[c.id,c.name]),v:x.customer}),fld('Source','source',{opts:['Phone','Email','Walk-in','Website',...CH],v:x.source}),fld('Product','product',{v:x.product}),fld('Quantity','qty',{t:'number',v:x.qty}),fld('Owner','owner',{opts:staff(),v:x.owner}),fld('Status','status',{opts:['New','In progress','Quoted','Won','Lost'],v:x.status||'New'}),fld('Details','notes',{area:1,full:1,v:x.notes})].join('')))};
F.enq=(d,id)=>{need('enquiries');if(id)Object.assign(by('enquiries',id),d);else S.enquiries.push({id:uid(),no:no('ENQ'),created:now(),...d});log(id?'Updated enquiry':'Added enquiry');close();route()};
const qT=q=>{const sub=q.lines.reduce((a,l)=>a+l.qty*l.price,0),rate=+(S.tax[by('customers',q.customer)?.province||S.province]||0),tax=sub*rate/100;return{sub,rate,tax,total:sub+tax}};
V.quotes=()=>shell('quotes',`<div class="card">${table(['No.','Customer','Total with tax','Promised delivery','Status',''],S.quotes.slice().reverse().map(q=>[e(q.no),e(nm('customers',q.customer)),money(qT(q).total),dt(q.promised),badge(q.status),button('Open','openQ',{id:q.id})]),'No quotations yet.')}</div>`,can('quotes','w')?button('New quotation','newQ',{},'b p'):'');
const qLines=(n=5,l=[])=>[...Array(n)].map((_,i)=>`<div class="full f" style="grid-template-columns:2fr 1fr 1fr">${fld(i?'':'Product or description','p'+i,{opts:[['','—'],...S.products.filter(p=>p.type==='Finished product').map(p=>[p.id,p.name])],v:l[i]?.product})}${fld(i?'':'Quantity','q'+i,{t:'number',v:l[i]?.qty})}${fld(i?'':'Unit price','u'+i,{t:'number',v:l[i]?.price})}</div>${S.offer==='crm'?`<div class="full">${fld('Description','t'+i,{v:l[i]?.desc})}</div>`:''}`).join('');
A.newQ=d=>{need('quotes');if(!S.customers.length)err('Add a customer first.');const x=d.enq?by('enquiries',d.enq):null;modal('New quotation',form('q',d.enq||'',fld('Customer','customer',{req:1,opts:S.customers.map(c=>[c.id,c.name]),v:x?.customer})+fld('Promised delivery','promised',{t:'date'})+qLines()+fld('Terms and notes','notes',{area:1,full:1}),'Save draft'))};
F.q=(d,enq)=>{need('quotes');const lines=[];for(let i=0;i<5;i++){const qty=+d['q'+i];if(!qty)continue;const p=by('products',d['p'+i]);lines.push({product:d['p'+i]||'',desc:p?.name||d['t'+i]||'',qty,price:d['u'+i]!==''?+d['u'+i]:+(p?.price||0)})}if(!lines.length)err('Add at least one line with a quantity.');if(lines.some(l=>!l.desc))err('Each line needs a product or description.');const q={id:uid(),no:no('QT'),created:now(),customer:d.customer,promised:d.promised,notes:d.notes,lines,status:'Draft',enquiry:enq||null};S.quotes.push(q);if(enq)by('enquiries',enq).status='Quoted';log('Created quotation',q.no);close();route()};
A.openQ=d=>{const q=by('quotes',d.id),t=qT(q),w=can('quotes','w');modal('Quotation '+q.no,`<p><b>${e(S.name)}</b><br>To: ${e(nm('customers',q.customer))}<br>Promised delivery: ${dt(q.promised)}</p>${table(['Item','Quantity','Unit price','Amount'],q.lines.map(l=>[e(l.desc),l.qty,money(l.price),money(l.qty*l.price)]))}<p style="text-align:right">Subtotal ${money(t.sub)}<br>Tax ${t.rate}% ${money(t.tax)}<br><b>Total ${money(t.total)}</b></p><p class="mut">${e(q.notes)}</p><div class="act noprint">${button('Print','print')}${w&&q.status==='Draft'?button('Mark sent','qs',{id:q.id,s:'Sent'}):''}${w&&['Draft','Sent'].includes(q.status)?button('Rejected','qs',{id:q.id,s:'Rejected'},'b d')+button('Approve','approve',{id:q.id},'b p'):''}</div>`)};A.print=()=>window.print();
A.qs=d=>{need('quotes');by('quotes',d.id).status=d.s;log('Quotation '+d.s);close();route()};
A.approve=d=>{need('quotes');const q=by('quotes',d.id);if(!q.promised)err('Confirm the promised delivery date before approval.');if(S.offer==='both'&&q.lines.some(l=>!l.product))err('Every line must be a catalogue product before it can pass to the factory.');q.status='Approved';q.approvedBy=me.name;q.approvedAt=now();if(q.enquiry)by('enquiries',q.enquiry).status='Won';let o;if(S.offer==='both'){o=mkOrder({customer:q.customer,quote:q.id,planned:q.promised,lines:q.lines.map(l=>({product:l.product,qty:l.qty}))});}log('Approved quotation',q.no);close();toast(o?'Approved. '+o.no+' sent to the factory.':'Quotation approved');route()};
V.opps=()=>shell('opps',`<div class="card">${table(['Opportunity','Customer','Value','Stage','Owner','Expected close',''],S.opps.map(o=>[e(o.name),e(nm('customers',o.customer)),money(o.value),badge(o.stage),e(by('users',o.owner)?.name||'Unassigned'),dt(o.close),can('opps','w')?button('Edit','ent',{k:'opps',id:o.id}):'']))}</div>`,can('opps','w')?button('Add opportunity','ent',{k:'opps'},'b p'):'');
V.followups=()=>{const r=S.followups.slice().sort((a,b)=>String(a.due).localeCompare(b.due));shell('followups',`<div class="card">${table(['Due','Customer','Needed','Assigned to','Status',''],r.map(f=>[dt(f.due)+(f.status==='Open'&&f.due<today()?' '+badge('Overdue'):''),e(nm('customers',f.customer)),e(f.note),e(by('users',f.owner)?.name||'Unassigned'),badge(f.status),can('followups','w')&&f.status==='Open'?button('Mark done','fDone',{id:f.id}):'']))}</div>`,can('followups','w')?button('Add follow-up','ent',{k:'followups'},'b p'):'')};
A.fDone=d=>{need('followups');const f=by('followups',d.id);f.status='Done';f.doneAt=now();log('Follow-up done');route()};
// ---- ERP
function mkOrder(d){const o={id:uid(),no:no('MO'),created:now(),stage:'Planned',blockers:[],costs:{labour:0,overhead:0},consumed:false,...d};S.orders.push(o);return o}
const reqs=o=>{const m={};for(const l of o.lines)for(const b of by('products',l.product)?.bom||[])m[b.id]=(m[b.id]||0)+b.qty*l.qty;return Object.entries(m).map(([id,qty])=>{const p=by('products',id);return{id,name:p?.name,qty,have:+p?.stock||0,short:Math.max(0,qty-(+p?.stock||0))}})};
const matCost=o=>reqs(o).reduce((a,r)=>a+r.qty*(+by('products',r.id)?.cost||0),0);
const move=(id,qty,why,ref)=>{const p=by('products',id);p.stock=(+p.stock||0)+qty;S.ledger.unshift({id:uid(),at:now(),product:id,qty,why,ref,by:me.name})};
V.orders=()=>shell('orders',`<div class="card">${table(['Order','Customer','Planned completion','Stage','Flags',''],S.orders.slice().reverse().map(o=>[e(o.no),e(o.customer?nm('customers',o.customer):o.ref||'Internal'),dt(o.planned),badge(o.stage),[late(o)?badge('Delayed'):'',blocked(o)?badge('Blocked'):''].join(' '),`<button class="b" data-go="#/order/${o.id}">Open</button>`]),'No factory orders yet.')}</div>`,can('orders','w')&&can('products')?button('New factory order','newO',{},'b p'):'');
A.newO=()=>{need('orders');const f=S.products.filter(p=>p.type==='Finished product');if(!f.length)err('Add a finished product first.');modal('New factory order',form('o','',fld('Reference','ref',{})+fld('Planned completion','planned',{req:1,t:'date'})+fld('Product','product',{req:1,opts:f.map(p=>[p.id,p.name])})+fld('Quantity','qty',{req:1,t:'number'})))};
F.o=d=>{need('orders');mkOrder({ref:d.ref,planned:d.planned,lines:[{product:d.product,qty:+d.qty}]});log('Created factory order');close();route()};
TI.order=['Factory order','Shared view from approval to delivery.'];
V.order=id=>{const o=by('orders',id);if(!o)return V.orders();const r=can('products')?reqs(o):[],w=can('orders','w'),i=STAGES.indexOf(o.stage),q=S.qc.filter(x=>x.order===id),sh=S.shipments.filter(x=>x.order===id),quote=o.quote?by('quotes',o.quote):null,cost=matCost(o)+(+o.costs.labour)+(+o.costs.overhead),short=r.some(x=>x.short>0&&!o.consumed);
 const nextBtn=()=>{if(!w)return'';if(o.stage==='Planned')return button('Confirm materials ready','stg',{id,to:'Materials ready'},'b p');if(o.stage==='Materials ready')return button('Start production','stg',{id,to:'In production'},'b p');if(o.stage==='In production')return button('Send to quality check','stg',{id,to:'Quality check'},'b p');if(o.stage==='Quality check')return button('Mark ready to ship','stg',{id,to:'Ready to ship'},'b p');return''};
 shell('orders',`<div class="card"><h3>${e(o.no)} ${e(o.customer?'· '+nm('customers',o.customer):'')}</h3><div class="steps">${STAGES.map((s,n)=>`<div class="st ${n<i?'d':n===i?'n':''}">${s}</div>`).join('')}</div><p>Planned completion: ${dt(o.planned)} ${late(o)?badge('Delayed'):''} ${quote?`· Quotation ${e(quote.no)}, promised ${dt(quote.promised)}, approved by ${e(quote.approvedBy)}`:''}</p><div class="row">${nextBtn()}${w?button('Record blocker','blk',{id}):''}</div></div><div class="two"><div>${can('products')?`<div class="card"><h3>Materials</h3>${table(['Material','Needed','In stock','Status'],r.map(x=>[e(x.name),x.qty,x.have,o.consumed?badge('Used'):x.short?badge('Shortage '+x.short):badge('OK')]),'Add a bill of materials to the product to plan materials.')}${short&&can('pos','w')?`<div class="act">${button('Create purchase orders for shortages','shortPo',{id})}</div>`:''}</div><div class="card"><h3>Costs</h3><dl><dt class="mut">Materials ${money(matCost(o))}</dt><dt class="mut">Labour ${money(o.costs.labour)}</dt><dt class="mut">Overhead ${money(o.costs.overhead)}</dt><dt><b>Total ${money(cost)}</b></dt></dl>${w?button('Update costs','cost',{id}):''}</div>`:''}<div class="card"><h3>Items</h3>${table(['Product','Quantity'],o.lines.map(l=>[e(nm('products',l.product)),l.qty]))}</div></div><div><div class="card"><h3>Blockers</h3>${table(['Recorded','Blocker','Status',''],(o.blockers||[]).map((b,n)=>[dt(b.at),e(b.text),badge(b.resolved?'Done':'Blocked'),w&&!b.resolved?button('Resolve','unblk',{id,n}):'']),'No blockers recorded.')}</div><div class="card"><h3>Quality checks</h3>${table(['Date','Result','Inspector','Notes'],q.map(x=>[dt(x.at),badge(x.result),e(x.by),e(x.notes)]))}${can('qc','w')?`<div class="act">${button('Record check','qcAdd',{id})}</div>`:''}</div><div class="card"><h3>Shipments</h3>${table(['Carrier','Tracking','Status',''],sh.map(x=>[e(x.carrier),e(x.tracking),badge(x.status),can('shipments','w')&&x.status==='Shipped'?button('Delivered','deliver',{id:x.id}):'']))}${can('shipments','w')&&o.stage==='Ready to ship'?`<div class="act">${button('Ship','ship',{id},'b p')}</div>`:''}</div></div></div>`,button('Back','go2',{to:'orders'}))};
A.stg=d=>{need('orders');const o=by('orders',d.id);if(blocked(o))err('Resolve the open blockers first.');const short=reqs(o).filter(x=>x.short>0);if(d.to==='Materials ready'&&short.length)err('Materials are short: '+short.map(x=>x.name).join(', '));if(d.to==='In production'){if(short.length)err('Materials are short: '+short.map(x=>x.name).join(', '));for(const r of reqs(o))move(r.id,-r.qty,'Used in production',o.no);o.consumed=true}if(d.to==='Ready to ship'){const l=S.qc.filter(x=>x.order===o.id).pop();if(!l||l.result!=='Pass')err('A passed quality check is required.')}o.stage=d.to;log('Order stage: '+d.to,o.no);route()};
A.blk=d=>modal('Record blocker',form('blk',d.id,fld('What is stopping work?','text',{req:1,area:1,full:1})));F.blk=(d,id)=>{need('orders');by('orders',id).blockers.push({at:now(),text:d.text});log('Blocker recorded',d.text);close();route()};A.unblk=d=>{need('orders');by('orders',d.id).blockers[d.n].resolved=now();log('Blocker resolved');route()};
A.cost=d=>{const o=by('orders',d.id);modal('Update costs',form('cost',d.id,fld('Labour','labour',{t:'number',v:o.costs.labour})+fld('Overhead','overhead',{t:'number',v:o.costs.overhead})))};F.cost=(d,id)=>{need('orders');by('orders',id).costs={labour:+d.labour||0,overhead:+d.overhead||0};close();route()};
A.shortPo=d=>{need('pos');const o=by('orders',d.id),g={};for(const r of reqs(o).filter(x=>x.short>0)){const s=by('products',r.id).supplier;if(!s)err(`Set a preferred supplier for ${r.name}.`);(g[s]=g[s]||[]).push({product:r.id,qty:r.short,cost:+by('products',r.id).cost||0})}for(const [s,lines] of Object.entries(g))S.pos.push({id:uid(),no:no('PO'),created:now(),supplier:s,lines,status:'Ordered',order:o.no});log('Purchase orders from shortages',o.no);toast('Purchase orders created');route()};
A.qcAdd=d=>modal('Record quality check',form('qc',d.id,fld('Result','result',{req:1,opts:['Pass','Fail']})+fld('Notes','notes',{area:1,full:1})));F.qc=(d,id)=>{need('qc');S.qc.push({id:uid(),order:id,at:now(),by:me.name,result:d.result,notes:d.notes});log('Quality check: '+d.result,by('orders',id).no);close();route()};
A.ship=d=>modal('Ship order',form('ship',d.id,fld('Carrier','carrier',{req:1})+fld('Tracking number','tracking')));F.ship=(d,id)=>{need('shipments');const o=by('orders',id);if(o.stage!=='Ready to ship')err('This order is not ready to ship.');S.shipments.push({id:uid(),order:id,at:now(),carrier:d.carrier,tracking:d.tracking,status:'Shipped'});o.stage='Shipped';log('Shipped',o.no);close();route()};
A.deliver=d=>{need('shipments');const s=by('shipments',d.id);s.status='Delivered';s.deliveredAt=now();by('orders',s.order).stage='Delivered';log('Delivered');route()};
V.products=()=>shell('products',`<div class="card">${table(['Name','SKU','Type','Cost','Price','Stock','Bill of materials',''],S.products.map(p=>[e(p.name),e(p.sku),e(p.type),money(p.cost),money(p.price),p.stock,e(p.bom.map(b=>`${b.qty} ${nm('products',b.id)}`).join(', ')),can('products','w')?button('Edit','ent',{k:'products',id:p.id})+(p.type==='Finished product'?' '+button('Materials','bom',{id:p.id}):''):'']))}</div>`,can('products','w')?button('Import CSV','imp',{k:'products'})+button('Add item','ent',{k:'products'},'b p'):'');
A.bom=d=>{const p=by('products',d.id),m=S.products.filter(x=>x.type==='Material');if(!m.length)err('Add a material first.');modal('Bill of materials: '+p.name,form('bom',d.id,[...Array(6)].map((_,i)=>fld('Material','m'+i,{opts:[['','—'],...m.map(x=>[x.id,x.name])],v:p.bom[i]?.id})+fld('Quantity per unit','q'+i,{t:'number',v:p.bom[i]?.qty})).join('')))};F.bom=(d,id)=>{need('products');const b=[];for(let i=0;i<6;i++)if(d['m'+i]&&+d['q'+i])b.push({id:d['m'+i],qty:+d['q'+i]});by('products',id).bom=b;log('Updated bill of materials');close();route()};
V.suppliers=()=>shell('suppliers',`<div class="card">${table(['Name','Contact','Email','Phone','Lead time',''],S.suppliers.map(s=>[e(s.name),e(s.contact),e(s.email),e(s.phone),e(s.lead),can('suppliers','w')?button('Edit','ent',{k:'suppliers',id:s.id}):'']))}</div>`,can('suppliers','w')?button('Add supplier','ent',{k:'suppliers'},'b p'):'');
V.pos=()=>shell('pos',`<div class="card">${table(['No.','Supplier','Items','Value','Status',''],S.pos.slice().reverse().map(p=>[e(p.no),e(nm('suppliers',p.supplier)),e(p.lines.map(l=>`${l.qty} ${nm('products',l.product)}`).join(', ')),money(p.lines.reduce((a,l)=>a+l.qty*l.cost,0)),badge(p.status),p.status==='Ordered'&&can('stock','w')?button('Receive','recv',{id:p.id}):'']))}</div>`,can('pos','w')?button('New purchase order','newPo',{},'b p'):'');
A.newPo=()=>{need('pos');if(!S.suppliers.length||!S.products.length)err('Add a supplier and an item first.');modal('New purchase order',form('po','',fld('Supplier','supplier',{req:1,opts:S.suppliers.map(s=>[s.id,s.name])})+fld('Item','product',{req:1,opts:S.products.map(p=>[p.id,p.name])})+fld('Quantity','qty',{req:1,t:'number'})+fld('Unit cost','cost',{t:'number'})))};F.po=d=>{need('pos');S.pos.push({id:uid(),no:no('PO'),created:now(),supplier:d.supplier,lines:[{product:d.product,qty:+d.qty,cost:d.cost!==''?+d.cost:+(by('products',d.product).cost||0)}],status:'Ordered'});log('Created purchase order');close();route()};
A.recv=d=>{need('stock');const p=by('pos',d.id);if(p.status!=='Ordered')err('Already received.');for(const l of p.lines)move(l.product,l.qty,'Received',p.no);p.status='Received';p.receivedAt=now();log('Received',p.no);toast('Stock updated');route()};
V.stock=()=>shell('stock',`<div class="card"><h3>Levels</h3>${table(['Item','Stock','Reorder level','Status'],S.products.map(p=>[e(p.name),p.stock+' '+e(p.unit),e(p.reorder),+p.reorder>0&&+p.stock<=+p.reorder?badge('Shortage'):badge('OK')]))}</div><div class="card"><h3>Movements</h3>${table(['Date','Item','Change','Reason','Reference','By'],S.ledger.slice(0,200).map(l=>[dt(l.at),e(nm('products',l.product)),l.qty,e(l.why),e(l.ref),e(l.by)]))}</div>`,can('stock','w')?button('Adjust stock','adj',{},'b p'):'');
A.adj=()=>{need('stock');if(!S.products.length)err('Add an item first.');modal('Adjust stock',form('adj','',fld('Item','product',{req:1,opts:S.products.map(p=>[p.id,p.name])})+`<div>${''}<label>Change (use - to reduce)</label><input name="qty" type="number" step="any" required></div>`+fld('Reason','why',{req:1,full:1})))};F.adj=d=>{need('stock');const q=+d.qty;if(+by('products',d.product).stock+q<0)err('Stock cannot go below zero.');move(d.product,q,d.why,'Adjustment');log('Stock adjusted',d.why);close();route()};
V.qc=()=>shell('qc',`<div class="card">${table(['Date','Order','Result','Inspector','Notes'],S.qc.slice().reverse().map(x=>[dt(x.at),`<button class="link" data-go="#/order/${x.order}">${e(by('orders',x.order)?.no)}</button>`,badge(x.result),e(x.by),e(x.notes)]))}</div>`);
V.shipments=()=>shell('shipments',`<div class="card">${table(['Shipped','Order','Carrier','Tracking','Status',''],S.shipments.slice().reverse().map(x=>[dt(x.at),`<button class="link" data-go="#/order/${x.order}">${e(by('orders',x.order)?.no)}</button>`,e(x.carrier),e(x.tracking),badge(x.status),x.status==='Shipped'&&can('shipments','w')?button('Delivered','deliver',{id:x.id}):'']))}</div>`);
// ---- chat automation (rules; messaging accounts need a server)
const COLLECT=[['name','Thanks for reaching out. May I have your name?'],['product','What product or service are you interested in?'],['qty','What quantity do you need?'],['contact','What is the best email or phone number to reach you?']];
function botReply(c,text,dry){const t=text.toLowerCase();if(/\b(agent|human|person|staff|representative)\b/.test(t)){if(!dry)c.state='Handoff';return'I will pass you to a member of our team.'}const f=S.faq.find(q=>q.keys.split(',').map(k=>k.trim().toLowerCase()).filter(Boolean).some(k=>t.includes(k)));if(f&&!c.step)return f.answer;if(dry)return f?f.answer:COLLECT[0][1];if(c.step){c.data[c.step]=text;}const nx=COLLECT.find(([k])=>!c.data[k]);if(nx){c.step=nx[0];return nx[1]}c.step=null;let cu=S.customers.find(x=>x.name.toLowerCase()===c.data.name.toLowerCase());if(!cu){const em=/@/.test(c.data.contact);cu={id:uid(),created:now(),name:c.data.name,email:em?c.data.contact:'',phone:em?'':c.data.contact,consent:'None'};S.customers.push(cu)}const q=S.enquiries.find(x=>x.conv===c.id);if(!q)S.enquiries.push({id:uid(),no:no('ENQ'),created:now(),customer:cu.id,source:c.channel,product:c.data.product,qty:c.data.qty,status:'New',owner:'',conv:c.id,notes:'Collected by chat automation'});c.customer=cu.id;c.state='Enquiry captured';log('Chat captured an enquiry',c.channel);return'Thank you. Our team has your details and will follow up soon.'}
V.chat=id=>{const c=id&&by('convs',id);const w=can('chat','w');shell('chat',`<div class="warn">Instagram, TikTok, WhatsApp and Facebook are not connected in this version. They need a server and each platform's business approval. Use this console to test how conversations will be handled.</div><div class="two"><div><div class="card"><h3>Conversations</h3>${table(['Channel','Customer','Status',''],S.convs.slice().reverse().map(x=>[e(x.channel),e(x.data.name||'Unknown'),badge(x.state),`<button class="b" data-go="#/chat/${x.id}">Open</button>`]),'No conversations yet.')}</div><div class="card"><h3>Routine answers</h3>${table(['Keywords','Answer',''],S.faq.map(f=>[e(f.keys),e(f.answer),w?button('Remove','faqDel',{id:f.id},'b d'):'']),'Add the answers the assistant may give.')}${w?`<form data-f="faq" class="stack" style="margin-top:10px">${fld('Keywords, separated by commas','keys',{req:1})}${fld('Answer','answer',{req:1,area:1})}<button class="b">Add answer</button></form>`:''}</div></div><div class="card">${c?`<h3>${e(c.channel)} ${badge(c.state)}</h3>${c.msgs.map(m=>`<div class="bub ${m.from}">${e(m.text)}<small>${m.from==='bot'?'Assistant':m.from==='staff'?'Staff':'Customer'}</small></div>`).join('')}${w?`<form data-f="say" data-id="${c.id}" class="stack" style="margin-top:12px">${fld('Customer writes','text',{})}<div class="row"><button class="b p">Send as customer</button>${c.state!=='Handoff'?button('Take over','takeover',{id:c.id}):''}</div></form>${c.state==='Handoff'?`<form data-f="staffSay" data-id="${c.id}" class="stack" style="margin-top:10px">${fld('Staff reply','text',{req:1})}<button class="b">Send staff reply</button></form>`:''}`:''}`:`<h3>Start a test conversation</h3>${w?`<form data-f="conv" class="stack">${fld('Channel','channel',{opts:CH})}<button class="b p">Start</button></form>`:'<div class="empty">Select a conversation.</div>'}`}</div></div>`)};
F.conv=d=>{need('chat');const c={id:uid(),created:now(),channel:d.channel,state:'Open',msgs:[],data:{},step:null};S.convs.push(c);location.hash='#/chat/'+c.id};
F.say=async(d,id,f)=>{need('chat');const c=by('convs',id);if(!d.text.trim())return;c.msgs.push({from:'customer',text:d.text,at:now()});if(c.state!=='Handoff'){const r=botReply(c,d.text);c.msgs.push({from:'bot',text:r,at:now()})}route()};
F.staffSay=(d,id)=>{need('chat');by('convs',id).msgs.push({from:'staff',text:d.text,at:now(),by:me.name});log('Staff chat reply');route()};
A.takeover=d=>{need('chat');by('convs',d.id).state='Handoff';log('Staff took over chat');route()};F.faq=d=>{need('chat');S.faq.push({id:uid(),...d});route()};A.faqDel=d=>{need('chat');S.faq=S.faq.filter(f=>f.id!==d.id);route()};
// ---- answers from records
const srcCard=(title,rows,src,period,upd)=>`<div class="card"><h3>${e(title)}</h3>${rows}<p class="mut" style="margin-top:10px"><b>Sources:</b> ${e(src)}<br><b>Period covered:</b> ${e(period)}<br><b>Last updated:</b> ${upd?dt(upd):'No records'}</p></div>`;
const latest=a=>a.map(x=>x.created||x.at).filter(Boolean).sort().pop();
V.ask=()=>{let o='';const q=sessionStorage.getItem('ask');if(q){const [k,id]=q.split('|');if(k==='leads'){const r=needFollow();o=srcCard('Which leads need a follow-up?',table(['Enquiry','Customer','Assigned','Last contact'],r.map(x=>[e(x.x.no),e(nm('customers',x.x.customer)),e(by('users',x.x.owner)?.name||'Unassigned'),dt(x.last)]),'No leads need a follow-up.'),`${r.length} of ${S.enquiries.length} enquiries, and follow-up records`,'All open enquiries',latest(S.enquiries))}if(k==='late'){const r=S.orders.filter(x=>late(x)||blocked(x));o=srcCard('Which production orders are delayed?',table(['Order','Stage','Planned completion','Blockers','Short materials'],r.map(x=>[e(x.no),badge(x.stage),dt(x.planned),e(x.blockers.filter(b=>!b.resolved).map(b=>b.text).join('; ')),e(reqs(x).filter(m=>m.short&&!x.consumed).map(m=>m.name).join(', '))]),'No production orders are delayed.'),`${S.orders.length} factory orders`,'Orders not yet shipped',latest(S.orders))}if(k==='cust'){const r=S.orders.filter(x=>x.customer===id);o=srcCard(`Status of orders for ${nm('customers',id)}`,table(['Order','Quotation','Stage','Promised','Last quality check','Shipment'],r.map(x=>{const qc=S.qc.filter(y=>y.order===x.id).pop(),s=S.shipments.filter(y=>y.order===x.id).pop();return[e(x.no),e(by('quotes',x.quote)?.no||'—'),badge(x.stage),dt(x.planned),qc?badge(qc.result):'None',s?`${e(s.carrier)} ${e(s.tracking)} ${badge(s.status)}`:'None']}),'No factory orders for this customer.'),'Linked quotations, factory orders, quality checks and shipments','All orders for this customer',latest(r))}}
 const b=[];if(S.offer!=='erp')b.push(button('Which leads need a follow-up?','ask',{k:'leads'}));if(S.offer!=='crm')b.push(button('Which production orders are delayed?','ask',{k:'late'}));shell('ask',`<div class="warn">These answers come from recorded information only. Connecting ChatGPT or Claude needs a server and is set up per client.</div><div class="card"><div class="row">${b.join('')}</div>${S.offer==='both'?`<form data-f="askC" class="row" style="margin-top:12px"><select name="c" aria-label="Customer" style="max-width:280px">${opt(S.customers.map(c=>[c.id,c.name]))}</select><button class="b">What is the status of this customer's order?</button></form>`:''}</div>${o}`)};
A.ask=d=>{sessionStorage.setItem('ask',d.k);route()};F.askC=d=>{sessionStorage.setItem('ask','cust|'+d.c);route()};
// ---- measures, launch, admin
V.reports=()=>{const eq=S.enquiries,d=S.followups.filter(f=>f.status==='Done'),ov=S.followups.filter(f=>f.status==='Open'&&f.due<today()),sh=S.orders.filter(o=>['Shipped','Delivered'].includes(o.stage)),on=sh.filter(o=>{const s=S.shipments.find(x=>x.order===o.id);return s&&s.at.slice(0,10)<=o.planned}),q=S.qc,fa=q.filter(x=>x.result==='Fail'),won=eq.filter(x=>x.status==='Won').length,li=(l,v)=>`<tr><td>${e(l)}</td><td style="text-align:right"><b>${v}</b></td></tr>`;shell('reports',`<div class="two">${S.offer!=='erp'?`<div class="card"><h3>Customer follow-ups</h3><table>${li('Enquiries recorded',eq.length)}${li('Enquiries won',won)}${li('Follow-ups completed',d.length)}${li('Follow-ups overdue',ov.length)}${li('Enquiries from chat automation',eq.filter(x=>x.conv).length)}</table></div>`:''}${S.offer!=='crm'?`<div class="card"><h3>Production visibility</h3><table>${li('Orders shipped',sh.length)}${li('Shipped on or before planned date',sh.length?Math.round(on.length/sh.length*100)+'%':'—')}${li('Quality checks recorded',q.length)}${li('Quality failures',fa.length)}${li('Blockers recorded',S.orders.reduce((a,o)=>a+o.blockers.length,0))}</table></div>`:''}</div><div class="card"><h3>Accounting exports</h3><p class="mut">CSV files for your bookkeeping software. Confirm tax rates with your accountant.</p><div class="row">${S.offer!=='erp'?button('Approved quotations','exp',{k:'q'})+button('Customers','exp',{k:'c'}):''}${S.offer!=='crm'?button('Purchase orders','exp',{k:'p'})+button('Order costs','exp',{k:'o'}):''}</div></div>`)};
A.exp=d=>{const X={q:()=>S.quotes.filter(q=>q.status==='Approved').map(q=>{const t=qT(q);return{number:q.no,date:q.approvedAt.slice(0,10),customer:nm('customers',q.customer),subtotal:t.sub.toFixed(2),tax_rate:t.rate,tax:t.tax.toFixed(2),total:t.total.toFixed(2)}}),c:()=>S.customers.map(({name,company,email,phone,city,province,consent})=>({name,company,email,phone,city,province,consent})),p:()=>S.pos.map(p=>({number:p.no,date:p.created.slice(0,10),supplier:nm('suppliers',p.supplier),total:p.lines.reduce((a,l)=>a+l.qty*l.cost,0).toFixed(2),status:p.status})),o:()=>S.orders.map(o=>({order:o.no,materials:matCost(o).toFixed(2),labour:o.costs.labour,overhead:o.costs.overhead,stage:o.stage}))};const r=X[d.k]();if(!r.length)err('Nothing to export yet.');log('Exported accounting data',d.k);dl(`bms-${d.k}.csv`,csv(r))};
const STEPS=[['Choose the right solution','Confirm the need for CRM, factory ERP, or CRM + ERP.'],['Configure and connect','Agree the scope, import approved data, define user roles, connect messaging accounts.'],['Test the setup','Check workflows, data accuracy, permissions, recovery and automated replies.'],['Train and launch','Train staff to use the system, review replies and take over conversations.'],['Review and improve','Measure use, administration time, errors and customer outcomes.']];
function runChecks(){const r=[];const t=(n,ok,x='')=>r.push({n,ok,x});const led={};S.ledger.forEach(l=>led[l.product]=(led[l.product]||0)+l.qty);t('Stock matches recorded movements',S.products.every(p=>Math.abs((+p.stock||0)-(led[p.id]||0))<1e-6));t('Every enquiry and quotation has a customer',[...S.enquiries,...S.quotes].every(x=>by('customers',x.customer)));t('Every order item exists',S.orders.every(o=>o.lines.every(l=>by('products',l.product))));const save=me.roles;try{me.roles=['warehouse'];t('A warehouse user cannot change quotations',!can('quotes','w'));me.roles=['sales'];t('A sales user cannot change production',!can('orders','w'));}finally{me.roles=save}t('Each person has a sign-in role',S.users.every(u=>u.roles.length));const copy=JSON.stringify(S);t('Backup restores identically',JSON.stringify(JSON.parse(copy))===copy);const test={msgs:[],data:{},step:null,id:'x',channel:'Test',state:'Open'};if(S.faq.length){const k=S.faq[0].keys.split(',')[0].trim();t('Automated reply answers a routine question',botReply(test,k,true)===S.faq[0].answer)}else t('Automated reply answers a routine question',false,'Add a routine answer first');t('A request for a person is handed to staff',botReply({...test},'I want a human',true).includes('team'));return r}
A.runC=()=>{S.checks={at:now(),r:runChecks()};log('Ran setup checks');route()};
V.launch=()=>{const w=can('launch','w');shell('launch',`${STEPS.map(([t,x],i)=>{const n=i+1,s=S.launch[n];return`<div class="card"><div class="row" style="justify-content:space-between"><h3 style="margin:0">${n}. ${e(t)}</h3>${badge(s.done?'Done':'Open')}</div><p class="mut">${e(x)}</p>${n===1?`<p>Selected: <b>${e(OFFERS[S.offer])}</b></p>`:''}${n===3?`${S.checks?`<p class="mut">Last run ${dt(S.checks.at)}</p>${table(['Check','Result',''],S.checks.r.map(c=>[e(c.n),badge(c.ok?'OK':'Fail'),e(c.x)]))}`:''}${w?`<p>${button('Run checks','runC')}</p>`:''}`:''}${w?`<form data-f="step" data-id="${n}" class="row">${`<input name="note" value="${e(s.note)}" placeholder="Notes" style="flex:1;min-width:200px" aria-label="Notes">`}<label style="margin:0"><input type="checkbox" name="done" ${s.done?'checked':''}> Done</label><button class="b">Save</button></form>`:''}</div>`}).join('')}`)};
F.step=(d,n)=>{need('launch');if(n==='3'&&d.done&&!(S.checks&&S.checks.r.every(c=>c.ok)))err('All setup checks must pass first.');S.launch[n]={done:!!d.done,note:d.note};log('Launch step '+n,d.done?'done':'open');route()};
V.admin=()=>shell('admin',`<div class="two"><div><div class="card"><h3>Users and access</h3>${table(['Name','Email','Roles','Status',''],S.users.map(u=>[e(u.name),e(u.email),e(u.roles.map(r=>ROLES[r]).join(', ')),badge(u.active?'Active':'Removed'),u.id!==me.id?button(u.active?'Remove access':'Restore','tUser',{id:u.id}):'']))}<div class="act">${button('Add user','addU',{},'b p')}</div></div><div class="card"><h3>Tax rates</h3><p class="mut">Starting rates by province. Confirm before use.</p><form data-f="tax"><div class="f" style="grid-template-columns:repeat(4,1fr)">${Object.keys(TAX).map(k=>fld(k,k,{t:'number',v:S.tax[k]})).join('')}</div><div class="act"><button class="b">Save rates</button></div></form></div></div><div><div class="card"><h3>Backup and recovery</h3><p class="mut">Records for this company stay in this browser.</p><div class="row">${button('Download backup','bak')}<label class="b" style="margin:0;font-weight:400">Restore<input type="file" accept=".json" style="display:none" onchange="A.rest(this)"></label></div></div><div class="card"><h3>Keeping and deleting data</h3><form data-f="ret" class="row">${`<input name="m" type="number" min="1" value="${S.retention}" style="max-width:100px" aria-label="Months">`}<span>months for closed enquiries</span><button class="b">Save</button></form><p>${button('Delete expired records','purge',{},'b d')}</p><form data-f="erase" class="row" style="margin-top:8px"><select name="c" aria-label="Customer" style="max-width:240px">${opt([['','Choose a customer'],...S.customers.map(c=>[c.id,c.name])])}</select><button class="b d">Erase customer</button></form></div><div class="card"><h3>Activity record</h3><div style="max-height:320px;overflow:auto">${table(['When','Who','Action'],S.audit.slice(0,200).map(a=>[new Date(a.at).toLocaleString('en-CA'),e(a.by),e(a.action+(a.detail?': '+a.detail:''))]))}</div></div></div></div><div class="card"><h3>Connections</h3>${table(['Connection','Status'],[...CH.map(c=>[c+' messaging']),['ChatGPT (MCP)'],['Claude (MCP)']].map(r=>[e(r[0]),badge('Needs server')]))}<p class="mut">Compatibility with ChatGPT or Claude does not imply a partnership or endorsement by OpenAI or Anthropic.</p></div>`);
A.addU=()=>modal('Add user',form('u','',fld('Name','name',{req:1})+fld('Email','email',{req:1,t:'email'})+fld('Temporary password (10+ characters)','password',{req:1,t:'password'})+`<div class="full"><label>Roles</label>${Object.entries(ROLES).map(([k,l])=>`<label style="font-weight:400;display:inline-block;margin-right:12px"><input type="checkbox" name="r_${k}"> ${l}</label>`).join('')}</div>`));
F.u=async d=>{need('admin');if(d.password.length<10)err('Password must be at least 10 characters.');const roles=Object.keys(ROLES).filter(r=>d['r_'+r]);if(!roles.length)err('Choose at least one role.');if(S.users.some(u=>u.email===d.email.toLowerCase()))err('This email already has an account.');S.users.push({id:uid(),name:d.name,email:d.email.toLowerCase(),roles,hash:await hash(d.password),active:true});log('Added user',d.name);close();route()};
A.tUser=d=>{need('admin');const u=by('users',d.id);u.active=!u.active;log(u.active?'Restored access':'Removed access',u.name);route()};
F.tax=d=>{need('admin');for(const k in d)S.tax[k]=+d[k];log('Updated tax rates');toast('Saved')};F.ret=d=>{need('admin');S.retention=+d.m;log('Updated retention',d.m+' months');toast('Saved')};
A.purge=()=>{need('admin');const c=new Date();c.setMonth(c.getMonth()-S.retention);const k=c.toISOString(),b=S.enquiries.length;S.enquiries=S.enquiries.filter(x=>!(['Won','Lost'].includes(x.status)&&x.created<k));log('Deleted expired records',String(b-S.enquiries.length));toast(`${b-S.enquiries.length} records deleted`);route()};
F.erase=d=>{need('admin');if(!d.c)err('Choose a customer.');if(!confirm('Erase this customer and their enquiries, follow-ups and chats? Orders and quotations stay for accounting, without the name.'))return;const c=by('customers',d.c);S.enquiries=S.enquiries.filter(x=>x.customer!==d.c);S.followups=S.followups.filter(x=>x.customer!==d.c);S.convs=S.convs.filter(x=>x.customer!==d.c);S.opps=S.opps.filter(x=>x.customer!==d.c);Object.assign(c,{name:'Erased customer',company:'',email:'',phone:'',city:'',notes:'',consent:'None'});log('Erased customer');route()};
A.bak=()=>{need('admin');log('Downloaded backup');dl(`${S.name}-backup.json`,JSON.stringify(S),'application/json')};
A.rest=async i=>{try{need('admin');const x=JSON.parse(await i.files[0].text());if(x.id!==S.id||!x.users)err('This backup is for a different company.');if(!confirm('Replace this company\'s records with the backup?'))return;S=x;me=S.users.find(u=>u.id===me.id)||S.users[0];log('Restored backup');await save();toast('Backup restored');route()}catch(x){toast(x.message,1)}};
// ---- French interface
const FR={'Overview':'Aperçu','Customers':'Clients','Enquiries':'Demandes','Quotations':'Soumissions','Sales opportunities':'Occasions de vente','Follow-ups':'Suivis','Factory orders':'Ordres de fabrication','Products and materials':'Produits et matières','Suppliers':'Fournisseurs','Purchasing':'Achats','Stock':'Stocks','Quality checks':'Contrôles qualité','Shipments':'Expéditions','Chat automation':'Clavardage automatisé','Ask your business':'Interroger vos données','Measures':'Indicateurs','Launch plan':'Plan de lancement','Users and data':'Utilisateurs et données','Sign out':'Déconnexion','What needs attention today.':'Ce qui demande votre attention aujourd\'hui.','Needs attention':'À traiter','Nothing needs attention right now.':'Rien à traiter pour le moment.','Name':'Nom','Company':'Entreprise','Contact':'Contact','Email':'Courriel','Phone':'Téléphone','City':'Ville','Province':'Province','Notes':'Notes','Status':'Statut','Owner':'Responsable','Source':'Source','Customer':'Client','Quantity':'Quantité','Product':'Produit','Save':'Enregistrer','Cancel':'Annuler','Edit':'Modifier','Open':'Ouvrir','Back':'Retour','Add customer':'Ajouter un client','Add enquiry':'Ajouter une demande','New quotation':'Nouvelle soumission','Add opportunity':'Ajouter une occasion','Add follow-up':'Ajouter un suivi','Add item':'Ajouter un article','Add supplier':'Ajouter un fournisseur','New purchase order':'Nouveau bon de commande','New factory order':'Nouvel ordre de fabrication','Import CSV':'Importer un CSV','Update':'Mettre à jour','Quote':'Soumettre','Approve':'Approuver','Rejected':'Refusée','Print':'Imprimer','Mark sent':'Marquer envoyée','Mark done':'Marquer terminé','Receive':'Recevoir','Ship':'Expédier','Delivered':'Livré','Shipped':'Expédié','Planned':'Planifié','Materials ready':'Matières prêtes','In production':'En production','Quality check':'Contrôle qualité','Ready to ship':'Prêt à expédier','Nothing recorded yet.':'Rien d\'enregistré pour le moment.','No enquiries yet.':'Aucune demande pour le moment.','No quotations yet.':'Aucune soumission pour le moment.','No factory orders yet.':'Aucun ordre de fabrication pour le moment.','Run checks':'Lancer les vérifications','Done':'Terminé','Materials':'Matières','Costs':'Coûts','Items':'Articles','Blockers':'Blocages','Users and access':'Utilisateurs et accès','Tax rates':'Taux de taxes','Backup and recovery':'Sauvegarde et récupération','Keeping and deleting data':'Conservation et suppression des données','Activity record':'Journal d\'activité','Connections':'Connexions','Download backup':'Télécharger la sauvegarde','Restore':'Restaurer','Add user':'Ajouter un utilisateur','Needs server':'Serveur requis','Active':'Actif','New':'Nouveau','Won':'Gagnée','Lost':'Perdue','Draft':'Brouillon','Sent':'Envoyée','Approved':'Approuvée','Pass':'Réussi','Fail':'Échec','Delayed':'En retard','Blocked':'Bloqué','Overdue':'En retard','Conversations':'Conversations','Routine answers':'Réponses courantes','Which leads need a follow-up?':'Quels prospects ont besoin d\'un suivi?','Which production orders are delayed?':'Quels ordres de fabrication sont en retard?','Take over':'Prendre le relais','Accounting exports':'Exportations comptables','Customer follow-ups':'Suivis clients','Production visibility':'Visibilité de la production','Levels':'Niveaux','Movements':'Mouvements','Adjust stock':'Ajuster les stocks','Add answer':'Ajouter une réponse','Email or password is incorrect.':'Courriel ou mot de passe incorrect.','Your role does not permit this action.':'Votre rôle ne permet pas cette action.','Add a customer first.':'Ajoutez d\'abord un client.'};
function tr(s){return S?.lang==='fr'&&FR[s]||s}
function translate(root){if(S?.lang!=='fr')return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const t=n.nodeValue.trim();if(t&&FR[t])n.nodeValue=n.nodeValue.replace(t,FR[t])}}
route().catch(x=>{$('#root').innerHTML=`<div class="auth"><div class="err">${e(x.message)}</div></div>`});
